// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Por que um guia de ética","html":"<p>A plataforma reúne três elementos que pedem cuidado: dados de crianças e adolescentes, inteligência artificial e informações sobre o desempenho de alunos, turmas e escolas.</p><p>Este guia apresenta os princípios que orientam o uso e as condutas esperadas de cada perfil. Ele complementa o guia do seu perfil e vale para todos os servidores com acesso.</p><h3>Ao final, você será capaz de</h3><ul><li>Reconhecer os princípios do uso ético da plataforma.</li><li>Distinguir o que a inteligência artificial faz do que cabe às pessoas.</li><li>Proteger os dados dos alunos e dos responsáveis no dia a dia.</li><li>Agir diante de um incidente ou de um uso indevido.</li></ul><div class=\"nota\"><b>Base legal</b><br/>Constituição Federal, art. 227 (prioridade absoluta da criança e do adolescente); Estatuto da Criança e do Adolescente (Lei nº 8.069/1990); Lei Geral de Proteção de Dados (Lei nº 13.709/2018), em especial o art. 14; e Lei nº 15.211/2025, sobre a proteção de crianças e adolescentes em ambientes digitais.</div>"},{"id":"c2","titulo":"Os seis princípios","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa</th><th>Exemplo</th></tr></thead><tbody><tr><td>Melhor interesse do aluno</td><td>Toda informação é usada para ajudar o aluno a aprender.</td><td>O mapa da turma orienta a retomada de um conteúdo.</td></tr><tr><td>Decisão humana</td><td>A inteligência artificial apoia. As decisões sobre o aluno são de pessoas.</td><td>O professor revisa o retorno de uma redação.</td></tr><tr><td>Transparência</td><td>Aluno e responsáveis sabem o que a plataforma faz e mostra.</td><td>A escola explica o reforço na reunião de responsáveis.</td></tr><tr><td>Equidade</td><td>Ninguém é prejudicado por falta de equipamento ou internet.</td><td>A escola abre o laboratório para quem não tem acesso em casa.</td></tr><tr><td>Sigilo</td><td>Os dados de um aluno só são vistos por quem precisa.</td><td>A tela não é projetada com nomes em reunião aberta.</td></tr><tr><td>Honestidade dos dados</td><td>Os números refletem o que aconteceu.</td><td>Ninguém responde pelo aluno para melhorar o indicador.</td></tr></tbody></table></div>"},{"id":"c3","titulo":"Inteligência artificial com responsabilidade","html":"<p>A plataforma usa inteligência artificial para orientar o estudo do aluno. Ela foi configurada com limites, e cabe à equipe conhecê-los.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A inteligência artificial</th><th>Situação</th></tr></thead><tbody><tr><td>Orienta o raciocínio do aluno com perguntas e dicas</td><td>Faz</td></tr><tr><td>Dá retorno sobre o texto do aluno, parágrafo por parágrafo</td><td>Faz</td></tr><tr><td>Entrega a resposta pronta ou reescreve o texto do aluno</td><td>Não faz</td></tr><tr><td>Recebe o nome ou a matrícula do aluno</td><td>Não recebe</td></tr><tr><td>Decide nota, aprovação ou encaminhamento do aluno</td><td>Não decide</td></tr></tbody></table></div><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Resposta do aluno</b><small>sem nome e sem matrícula</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Filtro de entrada</b><small>moderação automática</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Inteligência artificial</b><small>gera a dica</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Filtro de saída</b><small>moderação automática</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Aluno</b><small>recebe a orientação</small></div></div><figcaption>Figura. O caminho de uma resposta até o retorno ao aluno.</figcaption></figure><h3>O que cabe às pessoas</h3><ul><li>Acompanhar se as orientações fazem sentido para a turma.</li><li>Relatar dica inadequada ou conteúdo com erro.</li><li>Lembrar ao aluno que o tutor ajuda a pensar e não substitui o estudo.</li><li>Tomar todas as decisões pedagógicas sobre o aluno.</li></ul><div class=\"nota alerta\"><b>Se a inteligência artificial errar</b><br/>Toda tecnologia pode falhar. Anote a matéria, o ano e o que aconteceu e comunique à direção, que aciona a Secretaria. O relato melhora a plataforma para toda a rede.</div>"},{"id":"c4","titulo":"Uso dos dados de aprendizagem","html":"<p>Os dados mostram o momento do aluno em cada habilidade. Eles mudam conforme o aluno estuda e não são uma medida da capacidade dele nem da qualidade do professor.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Uso adequado</th><th>Uso inadequado</th></tr></thead><tbody><tr><td>Planejar a retomada de um conteúdo.</td><td>Dar nota ou compor média com o nível do mapa.</td></tr><tr><td>Identificar quem precisa de apoio.</td><td>Classificar, rotular ou separar alunos de forma permanente.</td></tr><tr><td>Decidir onde concentrar a formação de professores.</td><td>Avaliar, premiar ou punir professores.</td></tr><tr><td>Acompanhar a evolução de cada turma.</td><td>Publicar ranking de alunos, turmas ou escolas.</td></tr><tr><td>Conversar com o responsável sobre como apoiar.</td><td>Culpar o responsável ou o aluno pelo resultado.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · pedido de ranking</div><p><b>Situação.</b> Alguém da equipe propõe afixar no mural a lista das turmas que mais praticaram, para estimular a competição.</p><p><b>O que fazer.</b></p><ol><li>Lembre que as turmas têm condições de acesso diferentes.</li><li>Proponha reconhecer a evolução de cada turma em relação a ela mesma.</li><li>Use os dados para descobrir por que algumas turmas praticam menos.</li></ol><p><b>Resultado esperado.</b> A escola valoriza o esforço sem expor quem tem menos condição de acesso.</p></div>"},{"id":"c5","titulo":"Equidade e acesso","html":"<p>O reforço só é justo se todos puderem participar. A falta de equipamento ou de internet em casa não pode virar desvantagem para o aluno.</p><ol class=\"passos\"><li>Identifique os alunos que não praticam e converse para entender o motivo.</li><li>Se for falta de acesso, leve o caso à direção.</li><li>A escola organiza horários no laboratório, na biblioteca ou com equipamentos da rede.</li><li>Não cobre prática nem compare quem não tem condição de acessar.</li></ol><h3>Alunos com deficiência</h3><p>Converse com o professor de atendimento educacional especializado sobre a melhor forma de uso para cada aluno. Relate à Secretaria as barreiras encontradas, para que sejam tratadas com o fornecedor.</p>"},{"id":"c6","titulo":"Proteção de dados no dia a dia","html":"<p>A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) dá proteção reforçada aos dados de crianças e adolescentes. O Município é o responsável pelos dados da rede, e cada servidor responde pelo uso que faz do seu acesso.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dado</th><th>Quem vê</th><th>Cuidado</th></tr></thead><tbody><tr><td>Nome, turma e evolução do aluno</td><td>Professores da turma, direção, coordenação e Secretaria</td><td>Usar só para fins pedagógicos e de gestão.</td></tr><tr><td>Contato dos responsáveis</td><td>Direção e Secretaria</td><td>Não repassar a terceiros nem usar para outros assuntos.</td></tr><tr><td>Respostas e textos do aluno</td><td>Professores da turma</td><td>Não divulgar, mesmo como bom exemplo, sem autorização.</td></tr><tr><td>Seu usuário e senha</td><td>Só você</td><td>Não emprestar. Sair da conta em computador compartilhado.</td></tr></tbody></table></div><ul><li>Não publique telas com nome de aluno em redes sociais ou grupos de mensagens.</li><li>Para mostrar a plataforma em reuniões abertas, use dados de exemplo ou oculte os nomes.</li><li>Os dados dos alunos não são usados para publicidade nem cedidos a terceiros.</li><li>Quando um servidor deixa a escola, a direção ou a Secretaria desativa o acesso dele.</li></ul><div class=\"nota alerta\"><b>Incidente com dados</b><br/>Acesso indevido, senha compartilhada, tela exposta ou dado enviado à pessoa errada devem ser comunicados no mesmo dia à direção, que avisa a Secretaria. A Secretaria tem um encarregado de dados para tratar o caso.</div>"},{"id":"c7","titulo":"Conduta por perfil","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Perfil</th><th>Compromissos</th></tr></thead><tbody><tr><td>Professor</td><td>Usar o mapa para planejar. Não expor alunos. Não responder pelo aluno. Avisar os responsáveis com linguagem de apoio.</td></tr><tr><td>Coordenação pedagógica</td><td>Usar os dados para orientar a formação. Não classificar professores. Tratar com reserva o retorno das famílias.</td></tr><tr><td>Direção escolar</td><td>Garantir o acesso de alunos e responsáveis. Manter cadastros fiéis. Desativar acessos de quem saiu. Buscar alternativas para quem não tem equipamento.</td></tr><tr><td>Secretaria</td><td>Informar os responsáveis. Divulgar resultados de forma agregada. Controlar acessos e integrações. Tratar incidentes.</td></tr></tbody></table></div>"},{"id":"c8","titulo":"Comunicação com alunos e responsáveis","html":"<ul><li>Explique o reforço em linguagem simples: o que é, como entrar e o que o responsável vê.</li><li>Fale em evolução e em habilidades, não em nota.</li><li>Use a palavra responsável. Quem cuida do aluno pode ser mãe, pai, avó, avô, tia ou tio.</li><li>Use o contato do responsável apenas para assuntos do aluno.</li><li>Respeite quem não quer ou não pode acompanhar pelo celular. Ofereça outra forma de contato.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Ele não estuda.\"</td><td>\"Ele não praticou nas últimas semanas. Há algo que dificulte o acesso em casa?\"</td></tr><tr><td>\"Ela está entre os piores da turma.\"</td><td>\"Ela ainda está aprendendo frações. Com prática, costuma avançar.\"</td></tr><tr><td>\"O sistema disse que ele não sabe.\"</td><td>\"O reforço mostrou que ele precisa retomar este conteúdo.\"</td></tr></tbody></table></div>"},{"id":"c9","titulo":"O que fazer diante de um problema","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Perceber</b><small>acesso indevido, tela exposta, uso inadequado</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Interromper</b><small>sair da conta, apagar a mensagem</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>à direção, no mesmo dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Registrar</b><small>o que houve e quem foi afetado</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Tratar</b><small>a Secretaria e o encarregado de dados atuam</small></div></div><figcaption>Figura. Passos diante de um incidente.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td>Vi uma senha anotada na sala dos professores.</td><td>Avise o colega e a direção. A senha deve ser trocada.</td></tr><tr><td>Um colega pediu a minha senha para ver uma turma.</td><td>Não empreste. A direção pode dar o acesso correto a ele.</td></tr><tr><td>Enviei por engano uma tela com nomes a um grupo.</td><td>Apague a mensagem e comunique a direção no mesmo dia.</td></tr><tr><td>Um responsável pediu os dados de outro aluno.</td><td>Não forneça. Cada responsável vê apenas os alunos sob sua responsabilidade.</td></tr><tr><td>Notei que alguém responde pelos alunos.</td><td>Comunique à direção. Isso distorce o diagnóstico e prejudica o aluno.</td></tr></tbody></table></div>"},{"id":"c10","titulo":"O que as leis dizem","html":"<p>O uso de tecnologia com crianças e adolescentes na escola pública é orientado por um conjunto de leis. Elas têm um ponto em comum: o melhor interesse da criança vem antes de qualquer outra consideração.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Norma</th><th>O que estabelece</th><th>O que muda no uso da plataforma</th></tr></thead><tbody><tr><td>Constituição Federal (art. 227)</td><td>Prioridade absoluta aos direitos da criança e do adolescente.</td><td>Toda decisão sobre o uso considera primeiro o aluno.</td></tr><tr><td>Estatuto da Criança e do Adolescente</td><td>Direito ao respeito, à imagem, à identidade e à intimidade.</td><td>Nenhum aluno é exposto, comparado ou constrangido.</td></tr><tr><td>Lei Geral de Proteção de Dados (Lei 13.709/2018)</td><td>Regras para o tratamento de dados pessoais. O art. 14 exige que os dados de crianças e adolescentes sejam tratados no melhor interesse deles.</td><td>Usar apenas os dados necessários, para a finalidade educacional, com segurança e transparência.</td></tr><tr><td>Marco Civil da Internet (Lei 12.965/2014)</td><td>Direitos e deveres no uso da internet, com proteção da privacidade.</td><td>Cuidado com registros de acesso e com o que se publica.</td></tr><tr><td>Política Nacional de Educação Digital (Lei 14.533/2023)</td><td>Inclusão digital, educação digital nas escolas e formação.</td><td>O uso da tecnologia também ensina a usar a tecnologia.</td></tr><tr><td>Lei 15.100/2025</td><td>Restringe o uso de aparelhos eletrônicos pessoais pelos alunos na escola, com exceção para fins pedagógicos.</td><td>O uso do reforço em sala é atividade pedagógica orientada pelo professor.</td></tr><tr><td>Lei 15.211/2025</td><td>Proteção de crianças e adolescentes em ambientes digitais.</td><td>Reforça os deveres de segurança, de privacidade e de prevenção de riscos em produtos e serviços digitais.</td></tr><tr><td>Base Nacional Comum Curricular</td><td>Competência geral de cultura digital: usar tecnologias de forma crítica, significativa, reflexiva e ética.</td><td>O professor conversa com os alunos sobre como e por que usam a plataforma.</td></tr></tbody></table></div><h3>Quem é quem na proteção de dados</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Papel</th><th>Quem é</th><th>O que faz</th></tr></thead><tbody><tr><td>Titular</td><td>O aluno, o responsável, o servidor.</td><td>É a pessoa a quem os dados se referem. Tem direitos sobre eles.</td></tr><tr><td>Controlador</td><td>O Município.</td><td>Decide por que e como os dados são tratados.</td></tr><tr><td>Operador</td><td>A fornecedora da plataforma.</td><td>Trata os dados em nome do Município, conforme o contrato.</td></tr><tr><td>Encarregado</td><td>Pessoa indicada pelo Município.</td><td>Atende os titulares e orienta a rede.</td></tr><tr><td>Servidor com acesso</td><td>Você.</td><td>Usa os dados apenas para o trabalho e responde pelo próprio acesso.</td></tr></tbody></table></div>"},{"id":"c11","titulo":"Inteligência artificial em linguagem simples","html":"<p>A inteligência artificial usada no tutor é um programa treinado com grande quantidade de textos para produzir respostas em linguagem natural. Ela não pensa nem entende como uma pessoa. Calcula, a cada vez, qual resposta é mais provável e adequada ao que foi pedido.</p><p>Por isso ela consegue explicar de várias formas e adaptar a dica ao erro do aluno. E por isso também pode errar.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O que a inteligência artificial faz bem</th><th>Onde ela pode falhar</th></tr></thead><tbody><tr><td>Explicar a mesma ideia de formas diferentes.</td><td>Afirmar algo incorreto com aparência de certeza.</td></tr><tr><td>Dar exemplos e comparações.</td><td>Entender mal uma pergunta ambígua.</td></tr><tr><td>Ter paciência: responde quantas vezes o aluno perguntar.</td><td>Não perceber o estado emocional do aluno.</td></tr><tr><td>Adaptar a linguagem à idade.</td><td>Reproduzir visões parciais presentes nos textos com que foi treinada.</td></tr><tr><td>Dar retorno imediato.</td><td>Não conhecer a história e o contexto do aluno.</td></tr></tbody></table></div><h3>As salvaguardas da plataforma</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Risco</th><th>Como a plataforma trata</th></tr></thead><tbody><tr><td>O aluno receber a resposta pronta e não aprender</td><td>O tutor orienta com perguntas e dicas e não entrega a resposta.</td></tr><tr><td>Exposição de dados pessoais</td><td>O nome e a matrícula do aluno não são enviados à inteligência artificial.</td></tr><tr><td>A máquina decidir sobre o aluno</td><td>A plataforma não atribui nota nem decide aprovação. As decisões são de pessoas.</td></tr><tr><td>Conversas fora do estudo</td><td>O tutor é voltado ao conteúdo que o aluno está estudando.</td></tr><tr><td>Erro de conteúdo</td><td>Há um caminho para a escola comunicar e a correção valer para toda a rede.</td></tr><tr><td>Texto feito pela máquina no lugar do aluno</td><td>Nas redações, o retorno é sobre o texto do aluno. A plataforma não reescreve.</td></tr></tbody></table></div><div class=\"nota\"><b>Nenhuma salvaguarda dispensa o adulto</b><br/>As proteções reduzem os riscos. A observação do professor e da família continua sendo a principal garantia.</div>"},{"id":"c12","titulo":"A supervisão humana","html":"<p>A regra central do uso responsável de inteligência artificial na educação é que uma pessoa continue responsável pelas decisões. Na plataforma, isso significa que o professor, a gestão e a família acompanham, interpretam e decidem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quem</th><th>O que acompanha</th><th>O que decide</th></tr></thead><tbody><tr><td>Professor</td><td>O mapa da turma e o que observa em sala.</td><td>O que retomar, como agrupar, quando conversar com o aluno e a família.</td></tr><tr><td>Coordenação</td><td>As habilidades prioritárias e o uso pelos professores.</td><td>A pauta de formação e os apoios.</td></tr><tr><td>Direção</td><td>A prática por turma e o acesso dos alunos.</td><td>Horários, equipamentos e comunicação com as famílias.</td></tr><tr><td>Secretaria</td><td>Os indicadores da rede.</td><td>Prioridades, apoios e prestação de contas.</td></tr><tr><td>Responsável</td><td>A evolução do aluno.</td><td>A rotina de estudo em casa.</td></tr></tbody></table></div><h3>Três atitudes de quem supervisiona</h3><ul><li><b>Conferir:</b> não tomar o dado como verdade absoluta. Comparar com o que se observa.</li><li><b>Perguntar:</b> pedir ao aluno que explique o que fez. O raciocínio mostra mais do que o resultado.</li><li><b>Comunicar:</b> relatar o que parecer errado, para que seja corrigido.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Atitude adequada</th></tr></thead><tbody><tr><td>O mapa mostra Domina, mas o aluno não resolve em sala</td><td>Conversar com o aluno e com a família sobre como ele estuda.</td></tr><tr><td>O mapa mostra Ainda não, mas o aluno resolve bem em sala</td><td>Verificar se ele tem praticado e se entendeu a forma das questões.</td></tr><tr><td>Uma dica do tutor parece inadequada</td><td>Registrar o que ocorreu e comunicar à direção.</td></tr><tr><td>Um aluno diz que o tutor \"mandou\" fazer algo estranho</td><td>Ver a situação com o aluno e comunicar.</td></tr><tr><td>Um responsável questiona uma informação</td><td>Ouvir, verificar e dar retorno.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>A máquina não é desculpa</b><br/>\"Foi o sistema que mostrou\" não justifica uma decisão sobre um aluno. Quem decide é sempre uma pessoa, que responde pela decisão.</div>"},{"id":"c13","titulo":"O ciclo de vida dos dados","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Coleta</b><small>só o necessário</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Uso</b><small>para ensinar e gerir</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Guarda</b><small>com segurança</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Compartilhamento</b><small>só com quem precisa</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Eliminação</b><small>quando não é mais necessário</small></div></div><figcaption>Figura. As etapas do tratamento de dados.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>Princípio da lei</th><th>Na prática</th></tr></thead><tbody><tr><td>Coleta</td><td>Necessidade</td><td>A rede informa apenas os dados exigidos para o funcionamento do reforço.</td></tr><tr><td>Uso</td><td>Finalidade</td><td>Os dados servem à aprendizagem e à gestão educacional. Não a publicidade nem a outros fins.</td></tr><tr><td>Guarda</td><td>Segurança</td><td>Acesso com usuário individual. Senhas pessoais. Registro das ações.</td></tr><tr><td>Compartilhamento</td><td>Adequação</td><td>Cada perfil vê o que precisa. Pedidos externos passam pelo encarregado.</td></tr><tr><td>Eliminação</td><td>Limitação no tempo</td><td>Os dados são mantidos pelo tempo necessário e conforme o contrato e a lei.</td></tr><tr><td>Em todas</td><td>Transparência</td><td>Alunos e responsáveis sabem o que é tratado e para quê.</td></tr></tbody></table></div><h3>Os direitos dos titulares</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Direito</th><th>O que significa</th><th>Como a escola age</th></tr></thead><tbody><tr><td>Saber</td><td>Conhecer quais dados são tratados e para quê.</td><td>Explica e encaminha ao encarregado.</td></tr><tr><td>Acessar</td><td>Receber os dados que lhe dizem respeito.</td><td>Encaminha o pedido ao encarregado.</td></tr><tr><td>Corrigir</td><td>Ter dados errados ajustados.</td><td>Corrige o cadastro ou encaminha.</td></tr><tr><td>Questionar</td><td>Pedir esclarecimentos sobre o tratamento.</td><td>Ouve e encaminha.</td></tr></tbody></table></div><ol class=\"passos\"><li>O responsável faz o pedido à escola ou à Secretaria.</li><li>O servidor registra o pedido e não promete prazo por conta própria.</li><li>O pedido segue para o encarregado de dados do Município.</li><li>O encarregado responde dentro do prazo legal.</li><li>A escola acompanha e mantém o responsável informado.</li></ol><div class=\"nota\"><b>Dados de crianças</b><br/>No caso de crianças, os direitos são exercidos pelos pais ou responsáveis legais. A escola confirma quem é o responsável antes de entregar qualquer informação.</div>"},{"id":"c14","titulo":"Incidentes: reconhecer e agir","html":"<p>Incidente é qualquer situação em que dados pessoais ficam expostos, são acessados por quem não devia, se perdem ou são alterados indevidamente. A maioria não vem de ataque. Vem de descuido.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Exemplo</th><th>É incidente?</th><th>O que fazer</th></tr></thead><tbody><tr><td>Lista de acessos dos alunos fotografada e enviada ao grupo da turma</td><td>Sim</td><td>Pedir que apaguem, gerar novos acessos, comunicar à direção.</td></tr><tr><td>Professor deixou a conta aberta em computador da sala e saiu</td><td>Sim</td><td>Fechar a conta, trocar a senha, comunicar.</td></tr><tr><td>Tela do mapa da turma projetada com nomes em reunião de responsáveis</td><td>Sim</td><td>Interromper, pedir desculpas, comunicar à direção.</td></tr><tr><td>Planilha de alunos enviada ao e-mail errado</td><td>Sim</td><td>Pedir a exclusão ao destinatário e comunicar no mesmo dia.</td></tr><tr><td>Servidor que saiu da escola continua com acesso</td><td>Sim</td><td>Desativar e verificar o que foi acessado.</td></tr><tr><td>Tablet da escola perdido com conta aberta</td><td>Sim</td><td>Comunicar, gerar novo acesso e registrar a perda do equipamento.</td></tr><tr><td>Senha anotada em papel colado no monitor</td><td>Risco</td><td>Retirar e trocar a senha.</td></tr><tr><td>Aluno viu a própria evolução</td><td>Não</td><td>É o uso normal.</td></tr></tbody></table></div><h3>Passo a passo</h3><ol class=\"passos\"><li><b>Conter:</b> interromper a exposição. Fechar a conta, apagar a mensagem, recolher o papel.</li><li><b>Comunicar:</b> avisar a direção no mesmo dia. A direção avisa a Secretaria.</li><li><b>Registrar:</b> o que ocorreu, quando, que dados e quantas pessoas foram afetadas.</li><li><b>Corrigir:</b> trocar senhas, gerar novos acessos, desativar usuários.</li><li><b>Aprender:</b> o que mudar para não repetir.</li></ol><div class=\"nota alerta\"><b>Não esconda</b><br/>Um incidente comunicado cedo costuma ser resolvido sem dano. O que agrava a situação é o silêncio. Quem comunica de boa-fé está cumprindo o seu dever.</div><h3>Senhas e contas</h3><ul class=\"chk\"><li><span></span>A minha senha é só minha.</li><li><span></span>Uso uma senha diferente da de outros serviços.</li><li><span></span>Saio da conta em computadores compartilhados.</li><li><span></span>Não salvo a senha em navegador de uso comum.</li><li><span></span>Não entro em redes sem fio desconhecidas para acessar dados de alunos.</li><li><span></span>Aviso a direção se suspeitar que alguém usou o meu acesso.</li></ul>"},{"id":"c15","titulo":"O uso justo dos dados de aprendizagem","html":"<p>Saber o que cada aluno domina é uma informação poderosa. Ela pode servir para ensinar melhor ou para rotular. A diferença está no uso.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Uso que ajuda</th><th>Uso que prejudica</th></tr></thead><tbody><tr><td>Escolher o que retomar com a turma.</td><td>Separar turmas \"fortes\" e \"fracas\".</td></tr><tr><td>Formar grupos temporários por habilidade.</td><td>Fixar grupos permanentes por nível.</td></tr><tr><td>Conversar com o aluno sobre o próprio avanço.</td><td>Comparar alunos diante da turma.</td></tr><tr><td>Orientar a família sobre como apoiar.</td><td>Dizer à família que o aluno \"não tem jeito\".</td></tr><tr><td>Definir a pauta de formação.</td><td>Avaliar o professor pelo mapa da turma.</td></tr><tr><td>Identificar quem precisa de acesso.</td><td>Punir quem não praticou.</td></tr><tr><td>Reconhecer avanços.</td><td>Publicar rankings.</td></tr></tbody></table></div><h3>O risco do rótulo</h3><p>Quando um adulto passa a ver um aluno como \"o que está em Ainda não\", tende a esperar menos dele, a perguntar menos e a oferecer tarefas mais simples. O aluno percebe, e o desempenho cai. O nível na plataforma descreve uma habilidade em um momento. Não descreve o aluno.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de dizer</th><th>Diga</th></tr></thead><tbody><tr><td>\"Ele é fraco em Matemática.\"</td><td>\"Ele ainda não domina frações.\"</td></tr><tr><td>\"Essa turma é a pior.\"</td><td>\"Esta turma precisa retomar duas habilidades de base.\"</td></tr><tr><td>\"Os alunos do vermelho.\"</td><td>\"Os alunos que estão nesta habilidade.\"</td></tr><tr><td>\"Ele não vai conseguir.\"</td><td>\"Qual é o próximo passo para ele?\"</td></tr></tbody></table></div><h3>A honestidade dos dados</h3><ul><li>Ninguém responde pelo aluno, nem para ajudar.</li><li>Ninguém cria contas ou altera cadastros para melhorar indicadores.</li><li>Ninguém orienta alunos a \"passar pelas questões\" para aumentar a prática.</li><li>Números baixos são informados como são, com a explicação que houver.</li></ul><div class=\"pratica\"><div class=\"tt\">Para praticar · revise a sua prática</div><div class=\"q\"><b>1.</b> Você já usou, ou viu usarem, um dado de aprendizagem de um modo que prejudicou um aluno?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> O que poderia ter sido feito de outra forma?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c16","titulo":"Equidade e acessibilidade","html":"<p>Uma tecnologia pode reduzir desigualdades ou aumentá-las. Se só os alunos com aparelho e internet em casa praticam, o reforço amplia a distância que deveria diminuir.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Barreira</th><th>Quem afeta</th><th>O que fazer</th></tr></thead><tbody><tr><td>Falta de aparelho ou internet</td><td>Alunos de famílias com menos recursos.</td><td>Horário garantido na escola. Não cobrar prática em casa.</td></tr><tr><td>Aparelho compartilhado</td><td>Famílias com vários filhos.</td><td>Orientar sessões curtas e horários alternados.</td></tr><tr><td>Dificuldade de leitura</td><td>Alunos em alfabetização ou com dislexia.</td><td>Apoio de um adulto na leitura das questões. Mais tempo.</td></tr><tr><td>Deficiência visual, auditiva, motora ou intelectual</td><td>Alunos público da educação especial.</td><td>Recursos de acessibilidade do aparelho, apoio do atendimento especializado, adaptações combinadas com a família.</td></tr><tr><td>Pouca familiaridade com tecnologia</td><td>Alunos menores e famílias.</td><td>Primeira sessão acompanhada e ajuda presencial no cadastro.</td></tr><tr><td>Língua e cultura</td><td>Alunos migrantes, indígenas, quilombolas, do campo.</td><td>Mediação do professor e respeito ao contexto.</td></tr><tr><td>Ambiente de estudo em casa</td><td>Alunos sem lugar calmo.</td><td>Espaço e horário na escola.</td></tr></tbody></table></div><h3>Como saber se há desigualdade no uso</h3><ul><li>Compare a prática entre turmas e turnos.</li><li>Veja se os alunos sem atividade têm algo em comum: bairro, transporte, condição de acesso.</li><li>Pergunte aos professores quem não consegue usar e por quê.</li><li>Ouça as famílias que não criaram conta.</li></ul><div class=\"nota alerta\"><b>Não transfira a responsabilidade</b><br/>A falta de acesso não é falha do aluno nem da família. Garantir as condições de uso é dever da rede e da escola.</div>"},{"id":"c17","titulo":"Bem-estar no uso de telas","html":"<p>O reforço usa telas com finalidade pedagógica, em sessões curtas. Ainda assim, cabe à escola e à família cuidar para que esse tempo seja saudável.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Cuidado</th><th>Orientação</th></tr></thead><tbody><tr><td>Duração</td><td>Sessões de vinte a trinta minutos. Pouco tempo, várias vezes por semana, rende mais do que uma sessão longa.</td></tr><tr><td>Pausas</td><td>Depois de cada sessão, levantar, beber água, olhar para longe.</td></tr><tr><td>Postura</td><td>Tela na altura dos olhos, costas apoiadas, pés no chão.</td></tr><tr><td>Iluminação</td><td>Ambiente claro, sem reflexo na tela.</td></tr><tr><td>Horário</td><td>Evitar estudar em tela logo antes de dormir.</td></tr><tr><td>Ambiente</td><td>Lugar calmo, sem televisão ligada.</td></tr><tr><td>Acompanhamento</td><td>Um adulto por perto, sobretudo com os menores.</td></tr><tr><td>Equilíbrio</td><td>O reforço não substitui brincar, ler, conviver e descansar.</td></tr></tbody></table></div><h3>Sinais de que algo não vai bem</h3><ul><li>O aluno fica irritado ou muito ansioso ao usar.</li><li>Queixa-se de dor de cabeça ou nos olhos.</li><li>Passa a usar o aparelho para outras coisas no horário do estudo.</li><li>Chora ou se desespera quando erra.</li><li>Recusa-se a usar depois de uma experiência ruim.</li></ul><p>Diante desses sinais, o adulto conversa com o aluno, reduz o tempo, acompanha de perto e informa o professor.</p><div class=\"nota\"><b>O erro faz parte</b><br/>Alguns alunos sofrem muito ao errar. Vale dizer, mais de uma vez, que a plataforma serve para aprender, que não dá nota e que errar é o que mostra o que estudar.</div>"},{"id":"c18","titulo":"Integridade no estudo","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Por que é um problema</th><th>Como orientar</th></tr></thead><tbody><tr><td>Um colega dita as respostas</td><td>A trilha deixa de ensinar o que o aluno precisa.</td><td>Ensinar a turma a ajudar explicando.</td></tr><tr><td>O responsável responde junto</td><td>O nível deixa de refletir o que o aluno sabe.</td><td>Conversar com a família, com respeito.</td></tr><tr><td>O aluno copia a resposta de outra fonte</td><td>Acerta sem aprender.</td><td>Mostrar que não há nota em jogo e que só ele perde.</td></tr><tr><td>O aluno clica sem ler para terminar logo</td><td>Pratica sem aprender.</td><td>Combinar metas de qualidade, e não de quantidade.</td></tr><tr><td>O aluno usa o acesso de outro</td><td>Mistura os dados dos dois.</td><td>Explicar e gerar novo acesso.</td></tr><tr><td>Um adulto da escola responde para \"melhorar o número\"</td><td>Falseia os dados da rede.</td><td>É falta funcional. Comunicar à direção.</td></tr></tbody></table></div><h3>Conversar com os alunos sobre honestidade</h3><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · em sala</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Por que vocês acham que a plataforma não dá nota?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Para a gente não colar?</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Para vocês não precisarem colar. Se ninguém perde ponto por errar, o que se ganha copiando?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Nada. A gente só fica sem saber.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Isso. Aqui, o erro mostra o que estudar. Quem responde por você tira a sua chance de aprender.</div></div></div><h3>Inteligência artificial fora da plataforma</h3><p>Os alunos têm contato com outras ferramentas de inteligência artificial. A escola aproveita o reforço para ensinar o uso crítico.</p><ul><li>Uma ferramenta pode errar. Sempre se confere.</li><li>Pedir que a ferramenta faça o trabalho não ensina nada.</li><li>Usar para tirar dúvidas e pedir exemplos é diferente de copiar.</li><li>Dados pessoais não são informados a ferramentas desconhecidas.</li><li>O que foi feito com ajuda de uma ferramenta deve ser dito ao professor.</li></ul>"},{"id":"c19","titulo":"Transparência com as famílias","html":"<p>As famílias têm o direito de saber que a escola usa uma plataforma com inteligência artificial, para que ela serve e como os dados dos filhos são tratados. A transparência evita boatos e constrói confiança.</p><h3>O que toda família deve saber</h3><ul class=\"chk\"><li><span></span>O que é o reforço escolar e que ele não substitui a aula.</li><li><span></span>Que o aluno estuda no próprio ritmo e não recebe nota.</li><li><span></span>Que há um tutor com inteligência artificial que dá dicas e não dá respostas.</li><li><span></span>Que o nome e a matrícula do aluno não são enviados à inteligência artificial.</li><li><span></span>Quais dados são tratados e para quê.</li><li><span></span>Que os dados não são usados para publicidade.</li><li><span></span>Como acompanhar a evolução do aluno.</li><li><span></span>A quem recorrer em caso de dúvida ou pedido.</li></ul><h3>Modelo de comunicado</h3><div class=\"rapido\"><p><b>Senhores responsáveis,</b></p><p>A rede municipal oferece aos alunos uma plataforma de reforço escolar. Nela, cada aluno estuda as matérias do seu ano, no seu ritmo, com apoio de um tutor que usa inteligência artificial para dar dicas e fazer perguntas, sem entregar a resposta.</p><p>O reforço não dá nota e não substitui as aulas. Ele ajuda o aluno a recuperar o que ficou para trás.</p><p>Os dados dos alunos são usados somente para fins educacionais. O nome e a matrícula não são enviados à inteligência artificial, e nenhuma informação é usada para publicidade.</p><p>O senhor e a senhora podem acompanhar a evolução do aluno com o código entregue pela escola. Para dúvidas ou pedidos sobre dados pessoais, procurem a secretaria da escola.</p><p><b>Direção</b></p></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta da família</th><th>Resposta honesta</th></tr></thead><tbody><tr><td>\"Um robô vai ensinar meu filho?\"</td><td>\"Não. O professor continua ensinando. O tutor ajuda no estudo, com dicas.\"</td></tr><tr><td>\"Ele vai ficar viciado em tela?\"</td><td>\"As sessões são curtas, de vinte a trinta minutos, e têm finalidade de estudo.\"</td></tr><tr><td>\"A máquina pode errar?\"</td><td>\"Pode. Por isso os professores acompanham, e a escola comunica o que parecer errado.\"</td></tr><tr><td>\"Quem vê os dados do meu filho?\"</td><td>\"Os professores dele, a direção, a coordenação e a Secretaria, cada um no que precisa para o trabalho.\"</td></tr><tr><td>\"Posso não querer que ele use?\"</td><td>\"Vamos conversar sobre a sua preocupação. A direção orienta, com apoio da Secretaria.\"</td></tr></tbody></table></div>"},{"id":"c20","titulo":"Imagem, divulgação e redes sociais","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>Fotografar alunos usando os tablets</td><td>Só com autorização dos responsáveis e para divulgação pelos canais oficiais. Sem telas com dados visíveis.</td></tr><tr><td>Publicar uma tela da plataforma</td><td>Apenas com dados de exemplo ou com os nomes ocultos.</td></tr><tr><td>Divulgar o avanço de uma turma</td><td>Dados gerais, sem nomes. Com a concordância da direção.</td></tr><tr><td>Elogiar um aluno nas redes</td><td>Não em perfis pessoais. Reconhecimento se faz na escola e com a família.</td></tr><tr><td>Mostrar o texto de um aluno como exemplo</td><td>Só com autorização dele e dos responsáveis, sem identificação.</td></tr><tr><td>Apresentar resultados em evento</td><td>Dados da rede ou da escola, com data e fonte. Sem ranking.</td></tr><tr><td>Gravar uma aula com a plataforma</td><td>Com conhecimento de todos, autorização de imagem e sem dados pessoais na tela.</td></tr><tr><td>Responder a críticas nas redes</td><td>Não discutir. Encaminhar à direção ou à Secretaria.</td></tr></tbody></table></div><h3>Antes de divulgar, pergunte</h3><ul><li>Há nome, rosto ou dado de algum aluno?</li><li>Tenho autorização por escrito?</li><li>Algum aluno pode se sentir exposto ou diminuído?</li><li>A divulgação ajuda os alunos ou só promove alguém?</li><li>Estou usando o canal oficial?</li></ul><div class=\"nota\"><b>Reconhecimento que não expõe</b><br/>Dizer ao aluno e à família, em particular, o que ele conquistou vale mais do que uma publicação. E não deixa ninguém de fora.</div>"},{"id":"c21","titulo":"Dilemas para discutir","html":"<p>As situações abaixo não têm resposta óbvia. Sirva-se delas em reuniões de equipe. Para cada uma, pergunte: quem é afetado? O que dizem as regras? Que opção protege melhor o aluno?</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Pontos a considerar</th><th>Um caminho possível</th></tr></thead><tbody><tr><td>Um professor quer dar ponto extra a quem praticar mais.</td><td>Motiva alguns. Prejudica quem não tem acesso. Incentiva atalhos.</td><td>Reconhecer a constância sem nota e garantir horário na escola.</td></tr><tr><td>A direção quer afixar o gráfico de prática por turma no corredor.</td><td>Dá visibilidade. Expõe turmas e professores.</td><td>Mostrar o avanço da escola como um todo e tratar as turmas nas reuniões.</td></tr><tr><td>Um responsável pede para ver o desempenho dos colegas do filho.</td><td>Quer comparar. Os dados são de outras crianças.</td><td>Explicar que cada família vê apenas o próprio aluno.</td></tr><tr><td>Uma mãe pede que a filha não use o tutor.</td><td>Direito da família de opinar. Direito da aluna ao reforço.</td><td>Ouvir a preocupação, explicar as salvaguardas e levar à direção.</td></tr><tr><td>Um professor nota, em um texto no reforço, sinais de que o aluno sofre violência.</td><td>Sigilo do texto. Dever de proteção.</td><td>Comunicar à direção, que aciona o Conselho Tutelar.</td></tr><tr><td>A Secretaria pede à escola a lista dos alunos em Ainda não, com nomes, para um evento.</td><td>Pedido de superior. Exposição dos alunos.</td><td>Questionar a finalidade e oferecer dados sem identificação.</td></tr><tr><td>Um pesquisador pede acesso aos dados da escola.</td><td>Valor da pesquisa. Proteção dos dados.</td><td>Encaminhar à Secretaria e ao encarregado de dados.</td></tr><tr><td>Um aluno com deficiência não consegue usar sozinho.</td><td>Autonomia do aluno. Risco de alguém responder por ele.</td><td>Apoio na leitura e no manuseio, com a resposta sendo dele.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · escolha um dilema</div><div class=\"q\"><b>1.</b> Qual dessas situações já ocorreu, ou poderia ocorrer, na sua escola?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> O que você faria e por quê?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> A quem você pediria orientação?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c22","titulo":"A escola em conformidade","html":"<p>A lista abaixo ajuda a direção a verificar, uma vez por semestre, se a escola usa a plataforma de modo ético e seguro.</p><h3>Pessoas e acessos</h3><ul class=\"chk\"><li><span></span>Todo servidor com acesso leu este guia e assinou o termo de ciência.</li><li><span></span>Cada servidor usa o próprio acesso.</li><li><span></span>Servidores que saíram foram desativados.</li><li><span></span>Os perfis correspondem às funções.</li></ul><h3>Alunos e famílias</h3><ul class=\"chk\"><li><span></span>Os acessos foram entregues individualmente.</li><li><span></span>As famílias foram informadas sobre a plataforma e a inteligência artificial.</li><li><span></span>Os alunos sem acesso em casa têm horário na escola.</li><li><span></span>Nenhum aluno foi punido ou exposto por causa do reforço.</li><li><span></span>Os alunos com deficiência têm o apoio de que precisam.</li></ul><h3>Dados e divulgação</h3><ul class=\"chk\"><li><span></span>Não há listas de acessos afixadas ou em grupos de mensagens.</li><li><span></span>Telas com nomes não são projetadas em reuniões abertas.</li><li><span></span>Não há ranking de alunos, turmas ou professores.</li><li><span></span>Imagens de alunos só são divulgadas com autorização e pelos canais oficiais.</li><li><span></span>Pedidos de dados por terceiros são encaminhados ao encarregado.</li></ul><h3>Uso pedagógico</h3><ul class=\"chk\"><li><span></span>O nível do aluno na plataforma não é usado como nota.</li><li><span></span>Os professores usam o mapa para planejar.</li><li><span></span>Erros de conteúdo e dicas inadequadas são comunicados.</li><li><span></span>O tema da ética foi tratado em reunião neste semestre.</li></ul><div class=\"nota\"><b>Cada item não marcado é uma ação</b><br/>A lista não serve para punir. Serve para a equipe saber o que ajustar e combinar quem faz o quê, até quando.</div>"},{"id":"c23","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a lista no grupo</div><p><b>Situação.</b> Para facilitar, uma professora fotografa a folha com os acessos da turma e envia ao grupo dos responsáveis.</p><p><b>O que fazer.</b></p><ol><li>Pedir aos participantes que apaguem a imagem.</li><li>Comunicar à direção no mesmo dia.</li><li>Gerar novos acessos para a turma.</li><li>Entregar os novos acessos individualmente.</li><li>Relembrar à equipe a regra de entrega.</li></ol><p><b>Resultado esperado.</b> O risco é contido, e a escola revê o procedimento.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o ranking da turma</div><p><b>Situação.</b> Um professor projeta o mapa da turma e parabeniza \"os que estão no verde\".</p><p><b>O que fazer.</b></p><ol><li>A coordenação conversa com o professor em particular.</li><li>Explica o efeito sobre os alunos que não foram citados.</li><li>Sugere mostrar o avanço geral da turma.</li><li>O professor conversa individualmente com cada aluno sobre a própria evolução.</li></ol><p><b>Resultado esperado.</b> O reconhecimento continua, sem exposição.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a dica que confundiu</div><p><b>Situação.</b> Um aluno mostra ao professor uma dica do tutor que parece conter um erro.</p><p><b>O que fazer.</b></p><ol><li>Agradecer ao aluno por ter notado.</li><li>Explicar o conteúdo correto.</li><li>Registrar a questão e a dica e comunicar à direção.</li><li>Aproveitar para conversar com a turma: ferramentas podem errar, e conferir é parte de estudar.</li></ol><p><b>Resultado esperado.</b> O erro é comunicado para correção, e a turma aprende a ler com espírito crítico.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a conta aberta</div><p><b>Situação.</b> Um professor deixa a conta aberta no computador da sala. Um aluno vê o mapa da turma.</p><p><b>O que fazer.</b></p><ol><li>Fechar a conta e trocar a senha.</li><li>Comunicar à direção.</li><li>Conversar com o aluno, sem bronca, sobre o respeito às informações dos colegas.</li><li>Combinar com a equipe o hábito de sair da conta.</li></ol><p><b>Resultado esperado.</b> O incidente é registrado, e a prática de sair da conta se generaliza.</p></div>"},{"id":"c24","titulo":"Erros comuns e como evitá-los","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro</th><th>Por que é um problema</th><th>O que fazer</th></tr></thead><tbody><tr><td>Emprestar a senha a um colega</td><td>As ações ficam registradas no seu nome.</td><td>Cada um usa o próprio acesso.</td></tr><tr><td>Projetar o mapa da turma com nomes</td><td>Expõe os alunos.</td><td>Usar dados de exemplo ou ocultar os nomes.</td></tr><tr><td>Enviar acessos em grupos de mensagens</td><td>Qualquer pessoa pode entrar como o aluno.</td><td>Entregar individualmente, em mão.</td></tr><tr><td>Dar nota pelo desempenho na plataforma</td><td>Incentiva atalhos e prejudica quem não tem acesso.</td><td>Manter o reforço sem nota.</td></tr><tr><td>Responder com o aluno \"para ajudar\"</td><td>A trilha deixa de ensinar o que ele precisa.</td><td>Ajudar a ler e a entender a pergunta.</td></tr><tr><td>Formar grupos fixos por nível</td><td>Rotula os alunos.</td><td>Grupos temporários, por habilidade.</td></tr><tr><td>Confiar no dado sem conferir</td><td>O dado pode não refletir o que o aluno sabe.</td><td>Comparar com o que se observa em sala.</td></tr><tr><td>Não comunicar uma dica inadequada</td><td>O erro continua para outros alunos.</td><td>Registrar e comunicar à direção.</td></tr><tr><td>Esconder um incidente</td><td>O dano aumenta.</td><td>Conter e comunicar no mesmo dia.</td></tr><tr><td>Publicar fotos de alunos usando a plataforma</td><td>Fere o direito à imagem.</td><td>Divulgar só pelos canais oficiais, com autorização.</td></tr><tr><td>Deixar ativo o acesso de quem saiu</td><td>Pessoa de fora continua vendo dados.</td><td>Desativar no mesmo dia.</td></tr><tr><td>Esquecer as famílias</td><td>Surgem boatos e desconfiança.</td><td>Informar o que é, para que serve e como os dados são tratados.</td></tr></tbody></table></div><h3>Dez atitudes de quem usa bem</h3><ul class=\"chk\"><li><span></span>Uso só o meu acesso.</li><li><span></span>Saio da conta ao terminar.</li><li><span></span>Vejo os dados que preciso para o meu trabalho e nenhum outro.</li><li><span></span>Uso os dados para ajudar o aluno a aprender.</li><li><span></span>Não comparo nem exponho alunos.</li><li><span></span>Garanto que quem não tem acesso em casa estude na escola.</li><li><span></span>Não respondo pelo aluno.</li><li><span></span>Confiro o dado com o que observo.</li><li><span></span>Comunico o que parecer errado.</li><li><span></span>Explico às famílias, com palavras simples, como a plataforma funciona.</li></ul>"},{"id":"c25","titulo":"Mitos e verdades sobre a inteligência artificial na escola","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Mito</th><th>O que se sabe</th></tr></thead><tbody><tr><td>\"A inteligência artificial vai substituir o professor.\"</td><td>Ela apoia a prática do aluno. Ensinar, conhecer a turma e decidir continuam sendo trabalho de pessoas.</td></tr><tr><td>\"Ela sabe tudo.\"</td><td>Ela produz respostas prováveis, com base nos textos com que foi treinada. Pode errar.</td></tr><tr><td>\"Ela entende o aluno.\"</td><td>Ela reconhece padrões nas respostas. Não conhece a história nem o momento de vida do aluno.</td></tr><tr><td>\"Com ela, o aluno não precisa mais se esforçar.\"</td><td>No reforço, o tutor não dá a resposta. O esforço continua sendo do aluno.</td></tr><tr><td>\"Os dados dos alunos são vendidos.\"</td><td>Na rede, os dados são usados para fins educacionais, conforme o contrato e a lei, e não para publicidade.</td></tr><tr><td>\"Ela é neutra.\"</td><td>Ela pode reproduzir visões parciais dos textos de origem. Por isso há acompanhamento humano.</td></tr><tr><td>\"Se a máquina mostrou, é verdade.\"</td><td>O dado é uma informação a mais. O professor compara com o que observa.</td></tr><tr><td>\"Criança não deveria usar inteligência artificial.\"</td><td>O uso orientado, com finalidade pedagógica, tempo limitado e supervisão, é diferente do uso livre.</td></tr><tr><td>\"É complicado demais para eu entender.\"</td><td>Não é preciso entender a técnica. É preciso saber o que ela faz, o que não faz e quando desconfiar.</td></tr></tbody></table></div><h3>Como falar disso com os alunos</h3><ul><li>\"O tutor é um programa. Ele ajuda a pensar, mas pode errar.\"</li><li>\"Se uma dica parecer estranha, me mostre.\"</li><li>\"Ele não sabe quem você é. Não precisa contar coisas pessoais.\"</li><li>\"A resposta tem que ser sua. É assim que você aprende.\"</li><li>\"Fora daqui, outras ferramentas podem dar respostas prontas. Copiar não ensina.\"</li></ul><div class=\"nota\"><b>Educação digital</b><br/>Conversar sobre como a ferramenta funciona faz parte da formação dos alunos para o uso crítico da tecnologia, prevista na Base Nacional Comum Curricular e na Política Nacional de Educação Digital.</div>"},{"id":"c26","titulo":"Combinados de uso com os alunos","html":"<p>Os combinados abaixo podem ser construídos com cada turma e afixados na sala. Eles traduzem para os alunos os princípios deste guia.</p><div class=\"rapido\"><h3>Nossos combinados para o reforço</h3><ul><li>Eu uso o meu acesso e não empresto a ninguém.</li><li>Eu leio a pergunta até o fim antes de responder.</li><li>Eu tento antes de pedir a dica.</li><li>A resposta é minha. Ninguém responde por mim, e eu não respondo por ninguém.</li><li>Quando ajudo um colega, eu explico. Não dou a resposta.</li><li>Se eu errar, tudo bem. O erro mostra o que estudar.</li><li>Eu cuido do equipamento.</li><li>Eu não olho a tela do colega para comparar.</li><li>Se algo parecer estranho, eu aviso o professor.</li><li>Eu saio da minha conta quando termino.</li></ul></div><h3>Como construir com a turma</h3><ol class=\"passos\"><li>Pergunte: \"o que precisamos combinar para todos aprenderem no reforço?\"</li><li>Registre as ideias no quadro, com as palavras dos alunos.</li><li>Agrupe as parecidas e chegue a poucos combinados.</li><li>Verifique se os pontos essenciais apareceram. Se não, proponha.</li><li>Escreva em um cartaz, assinado pela turma.</li><li>Retome o cartaz no início das primeiras sessões.</li></ol><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>Como adaptar</th></tr></thead><tbody><tr><td>Anos iniciais</td><td>Menos combinados, com desenhos. Frases curtas: \"o acesso é meu\", \"eu tento primeiro\".</td></tr><tr><td>Anos finais</td><td>Discussão sobre o porquê de cada combinado. Incluir o uso de outras ferramentas de inteligência artificial.</td></tr></tbody></table></div><h3>Para os responsáveis</h3><ul><li>Combinem um horário e um lugar para o estudo.</li><li>Fiquem por perto, sobretudo com os menores.</li><li>Ajudem a ler a pergunta, e deixem a resposta com o aluno.</li><li>Perguntem o que ele aprendeu, e não quantas acertou.</li><li>Avisem a escola se algo preocupar.</li></ul>"},{"id":"c27","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td>Preciso de autorização dos responsáveis para o aluno usar a plataforma?</td><td>O uso faz parte da atividade educacional da rede. A transparência com as famílias é obrigatória. A Secretaria orienta sobre os termos adotados.</td></tr><tr><td>Posso tirar uma foto da tela para mostrar a um colega?</td><td>Sem nomes de alunos, e apenas para fins de trabalho.</td></tr><tr><td>Posso usar o meu celular pessoal para acessar?</td><td>Pode, com cuidado: tela bloqueada por senha e saída da conta ao terminar.</td></tr><tr><td>Um responsável pede que eu informe o nível de outro aluno.</td><td>Não informe. Cada família vê apenas o próprio aluno.</td></tr><tr><td>Posso usar os dados da turma em um trabalho acadêmico?</td><td>Só com autorização da Secretaria e orientação do encarregado de dados.</td></tr><tr><td>O aluno escreveu algo pessoal para o tutor.</td><td>Oriente a não fazer. Se o conteúdo indicar risco, comunique à direção.</td></tr><tr><td>O que acontece com os dados do aluno que sai da rede?</td><td>São tratados conforme o contrato e a lei. Dúvidas vão ao encarregado de dados.</td></tr><tr><td>Posso criar um acesso de teste com dados inventados?</td><td>Peça à Secretaria. Não crie alunos fictícios nas turmas reais.</td></tr><tr><td>A família não quer que o aluno use.</td><td>Ouça, explique as salvaguardas e leve à direção.</td></tr><tr><td>Posso mostrar a plataforma a um visitante?</td><td>Com dados de exemplo ou nomes ocultos.</td></tr><tr><td>Emprestei a minha senha a um colega em uma urgência.</td><td>Troque a senha e comunique à direção. Não repita.</td></tr><tr><td>Tenho uma sugestão de melhoria.</td><td>Envie à direção ou à Secretaria. As sugestões da rede chegam à fornecedora.</td></tr></tbody></table></div>"},{"id":"c28","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"Uso dos dados de aprendizagem\"</td><td>O que a inteligência artificial faz e não faz na plataforma? Como explicamos isso às famílias?</td></tr><tr><td>2</td><td>De \"Equidade e acesso\" até \"Comunicação com alunos e responsáveis\"</td><td>Quem são os alunos sem acesso? Que cuidados com dados já praticamos?</td></tr><tr><td>3</td><td>De \"O que fazer diante de um problema\" até \"Incidentes\"</td><td>Já tivemos um incidente? O que fizemos? O que faríamos hoje?</td></tr><tr><td>4</td><td>De \"O uso justo dos dados\" até \"Integridade no estudo\"</td><td>Há algum uso de dados que rotula alunos aqui? Como combinamos a honestidade com as turmas?</td></tr><tr><td>5</td><td>De \"Transparência com as famílias\" até o final</td><td>Discussão de três dilemas, lista de conformidade da escola e assinatura do termo de ciência.</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c29","titulo":"Termo de ciência","html":"<p>Modelo para registro da formação. A Secretaria pode adaptar o texto.</p><div class=\"rapido\"><p>Declaro que li o Guia de ética e uso responsável da plataforma de reforço escolar da rede municipal e que me comprometo a:</p><ul class=\"chk\"><li><span></span>Usar a plataforma apenas para fins pedagógicos e de gestão da rede.</li><li><span></span>Manter o meu acesso pessoal e não compartilhar a minha senha.</li><li><span></span>Proteger os dados de alunos e responsáveis e não divulgá-los.</li><li><span></span>Não usar os dados para expor, classificar ou punir alunos e professores.</li><li><span></span>Comunicar à direção, no mesmo dia, qualquer incidente ou uso indevido.</li></ul><p style=\"margin-top:8mm\">Nome: ____________________________________________ &nbsp; Matrícula: ________________</p><p>Escola ou setor: ________________________________________________________________</p><p>Data: ____/____/________ &nbsp;&nbsp; Assinatura: _____________________________________________</p></div>"},{"id":"c30","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Quem toma as decisões pedagógicas sobre o aluno?</p><ol type=\"a\"><li>A inteligência artificial.</li><li>A plataforma.</li><li>As pessoas da equipe.</li><li>O fornecedor.</li></ol></div><div class=\"qz\"><p><b>2.</b> O que a inteligência artificial recebe sobre o aluno?</p><ol type=\"a\"><li>Nome e matrícula.</li><li>A resposta, sem nome e sem matrícula.</li><li>O endereço.</li><li>O contato do responsável.</li></ol></div><div class=\"qz\"><p><b>3.</b> Qual é um uso adequado dos dados de aprendizagem?</p><ol type=\"a\"><li>Avaliar professores.</li><li>Ranking de turmas.</li><li>Nota do bimestre.</li><li>Planejar a retomada de um conteúdo.</li></ol></div><div class=\"qz\"><p><b>4.</b> Um aluno não pratica por falta de internet em casa. O correto é:</p><ol type=\"a\"><li>Levar o caso à direção para organizar uma alternativa de acesso.</li><li>Retirar o aluno do reforço.</li><li>Avisar o responsável de que a culpa é dele.</li><li>Cobrar mesmo assim.</li></ol></div><div class=\"qz\"><p><b>5.</b> Você enviou por engano uma tela com nomes de alunos. O que fazer?</p><ol type=\"a\"><li>Apagar e comunicar a direção no mesmo dia.</li><li>Esperar alguém reclamar.</li><li>Pedir segredo ao grupo.</li><li>Nada.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> c) As pessoas da equipe. A inteligência artificial apoia; a decisão é humana.</p><p><b>2.</b> b) A resposta, sem nome e sem matrícula. O envio é feito sem identificar o aluno.</p><p><b>3.</b> d) Planejar a retomada de um conteúdo. Os dados servem para apoiar a aprendizagem.</p><p><b>4.</b> a) Levar o caso à direção para organizar uma alternativa de acesso. Equidade: ninguém pode ser prejudicado por falta de acesso.</p><p><b>5.</b> a) Apagar e comunicar a direção no mesmo dia. Incidentes são comunicados no mesmo dia.</p></div>"},{"id":"c31","titulo":"Glossário","html":"<dl><dt>BNCC</dt><dd>Base Nacional Comum Curricular. Define as habilidades que o aluno deve desenvolver em cada ano e componente.</dd><dt>Componente curricular</dt><dd>Cada matéria do currículo: Língua Portuguesa, Matemática, Ciências e as demais.</dd><dt>Diagnóstico</dt><dd>Conjunto curto de questões que mostra quais habilidades o aluno já domina.</dd><dt>Encarregado de dados</dt><dd>Pessoa indicada para receber pedidos dos titulares e tratar incidentes.</dd><dt>Equidade</dt><dd>Garantir a todos as condições de participar, considerando as diferenças de acesso.</dd><dt>Habilidade</dt><dd>O que o aluno deve saber fazer. É a unidade que a plataforma acompanha.</dd><dt>Habilidade recuperada</dt><dd>Habilidade em que o aluno saiu de Ainda não ou Quase lá e chegou a Domina.</dd><dt>Incidente</dt><dd>Qualquer acesso, uso ou divulgação indevida de dados pessoais.</dd><dt>Nível de domínio</dt><dd>Situação do aluno em uma habilidade: Ainda não, Quase lá ou Domina.</dd><dt>Pré-requisito</dt><dd>Habilidade anterior que serve de base para outra.</dd><dt>Responsável</dt><dd>Adulto que cuida do aluno e o acompanha na plataforma.</dd><dt>Trilha</dt><dd>Sequência de estudo de uma habilidade, em cinco etapas.</dd><dt>Tutor</dt><dd>Apoio com inteligência artificial que orienta o aluno com perguntas e dicas.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"Pela Lei Geral de Proteção de Dados, os dados de crianças são tratados:","alternativas":["Para qualquer finalidade pública.","Como os de adultos.","No melhor interesse da criança.","Sem restrições na escola."],"correta":2,"explicacao":"É o que estabelece o art. 14."},{"pergunta":"Na rede, o controlador dos dados é:","alternativas":["O professor.","O aluno.","A fornecedora.","O Município."],"correta":3,"explicacao":"A fornecedora é operadora."},{"pergunta":"A inteligência artificial do tutor:","alternativas":["Pode errar, por isso há supervisão humana.","Decide a nota.","Recebe o nome do aluno.","Nunca erra."],"correta":0,"explicacao":"Nenhuma salvaguarda dispensa o adulto."},{"pergunta":"\"Foi o sistema que mostrou\" justifica uma decisão sobre o aluno?","alternativas":["Não. Quem decide é uma pessoa, que responde pela decisão.","Só na Secretaria.","Só em reunião.","Sim."],"correta":0,"explicacao":"A máquina apoia, não decide."},{"pergunta":"Diante de um incidente com dados, o primeiro passo é:","alternativas":["Conter a exposição e comunicar no mesmo dia.","Esperar alguém reclamar.","Publicar.","Esconder."],"correta":0,"explicacao":"Conter, comunicar, registrar, corrigir, aprender."},{"pergunta":"Formar grupos permanentes por nível com base no mapa é:","alternativas":["Obrigatório.","Indiferente.","Recomendado.","Um uso que rotula e prejudica."],"correta":3,"explicacao":"Grupos são temporários e por habilidade."},{"pergunta":"Um responsável pede para ver o desempenho dos colegas do filho. A escola:","alternativas":["Cobra uma taxa.","Mostra.","Explica que cada família vê apenas o próprio aluno.","Envia por mensagem."],"correta":2,"explicacao":"São dados de outras crianças."},{"pergunta":"Um adulto da escola responde pelo aluno para melhorar o indicador. Isso é:","alternativas":["Boa prática.","Ajuda.","Falta funcional que falseia os dados.","Permitido uma vez."],"correta":2,"explicacao":"Honestidade dos dados."}];
